class TestClock extends Clock {
 private fixed?:Date;
 // 创建大批真实DB夹具时跟随墙钟；显式推进时间后固定，保留期限/暂停的精确断言。
 get value(){return this.now();}
 set value(value:Date){this.fixed=new Date(value);}
 followWallClock(){this.fixed=undefined;}
 now(){return this.fixed?new Date(this.fixed):new Date();}
}
class ControlledAudit extends AuditService {
 fail?:string;
 barrier?:{matches:(p:AuditPayload)=>boolean;entered:()=>void;release:Promise<void>};
 override async appendAudit(tx:Prisma.TransactionClient,p:AuditPayload){
  await super.appendAudit(tx,p);
  const gate=this.barrier;if(gate?.matches(p)){this.barrier=undefined;gate.entered();await gate.release;}
  if(this.fail===p.action)throw new Error('本轮独占库故障注入');
 }
}
