async function saleBody(id:string,stage:TaskStage='AFTER_SALE_REVIEW'){const a=await db.afterSale.findUniqueOrThrow({where:{id}}),t=await db.task.findFirst({where:{businessType:'AFTER_SALE',businessId:id,stage,status:{in:['OPEN','CLAIMED','SUSPENDED']}},orderBy:{round:'desc'}});return {commandKey:randomUUID(),expectedAfterSaleVersion:a.version,expectedTaskVersion:t?.version??0};}
