it('真实申请→两轮补充→撤销→发货新轮；原键重放不复活、金额库存无副作用',async()=>{
 const f=await ready(),b={orderId:f.id,type:'REFUND_ONLY' as const,reasonCode:'QUALITY',description:'原材料',evidenceFileIds:[],commandKey:randomUUID()};const a=await sales().apply(f.c,b);expect(a.amountCents).toBe((await db.payment.findUniqueOrThrow({where:{orderId:f.id}})).amountCents);expect(await db.order.findUnique({where:{id:f.id}})).toMatchObject({status:'WAIT_SHIPMENT',shipmentReclaimRequired:true});expect(await db.task.findFirst({where:{businessId:f.id,stage:'SHIPMENT_PROCESS'}})).toMatchObject({status:'SUSPENDED',assigneeId:null});await expect(start(f.id)).rejects.toBeDefined();
 for(let i=0;i<2;i++){await review(a.afterSaleId,'REQUEST_SUPPLEMENT',{requirement:'补充衣服全貌'+i,internalNote:'不公开的员工意见'});await expect(sales().withdraw(f.c,a.afterSaleId,await saleBody(a.afterSaleId))).rejects.toMatchObject({code:'AFTER_SALE_ACTION_NOT_ALLOWED'});const d=await detail(a.afterSaleId,f.c),request=d.supplementRequests.at(-1)!;const body={...await saleBody(a.afterSaleId),supplementRequestId:request.id,description:'第'+(i+2)+'版完整替换',evidenceFileIds:[]};const first=await sales().supplement(f.c,a.afterSaleId,body);expect(await sales().supplement(f.c,a.afterSaleId,body)).toMatchObject({materialVersionId:first.materialVersionId,replayed:true});expect(await db.task.findFirst({where:{businessId:a.afterSaleId,stage:'AFTER_SALE_REVIEW',round:i+2}})).toMatchObject({status:'OPEN',assigneeId:null});}
 const d=await detail(a.afterSaleId,f.c);expect(d.materialVersions).toHaveLength(3);expect(JSON.stringify(d)).not.toContain('不公开');await sales().withdraw(f.c,a.afterSaleId,await saleBody(a.afterSaleId));expect(await sales().apply(f.c,b)).toMatchObject({afterSaleId:a.afterSaleId,status:'WITHDRAWN',replayed:true});expect(await db.task.findFirst({where:{businessId:f.id,stage:'SHIPMENT_PROCESS',round:2}})).toMatchObject({status:'OPEN',assigneeId:null});expect(await db.fulfillment.findUnique({where:{orderId:f.id}})).toMatchObject({currentPackingCheckId:null});expect(await db.inventoryBalance.findUnique({where:{skuId:f.sku.id}})).toMatchObject({available:8,reserved:0});expect(await db.payment.count({where:{orderId:f.id}})).toBe(1);
});
it('同订单100并发不同key只有一单；同key100重放同结果，异载荷冲突',async()=>{const f=await paid(),results=await Promise.allSettled(Array.from({length:100},()=>apply(f)));expect(results.filter(r=>r.status==='fulfilled')).toHaveLength(1);for(const r of results)if(r.status==='rejected')expect(['AFTER_SALE_ALREADY_ACTIVE','REQUEST_IN_PROGRESS']).toContain(r.reason.code);const g=await paid(),b={orderId:g.id,type:'REFUND_ONLY' as const,reasonCode:'OTHER',description:'幂等',evidenceFileIds:[],commandKey:randomUUID()};const settled=await Promise.allSettled(Array.from({length:100},()=>sales().apply(g.c,b)));for(const r of settled)if(r.status==='rejected')expect(r.reason.code).toBe('REQUEST_IN_PROGRESS');const same=[];for(const r of settled)same.push(r.status==='fulfilled'?r.value:await sales().apply(g.c,b)); expect(new Set(same.map(r=>r.afterSaleId)).size).toBe(1);expect(same.filter(r=>!r.replayed)).toHaveLength(1);await expect(sales().apply(g.c,{...b,description:'变化'})).rejects.toMatchObject({code:'COMMAND_PAYLOAD_CONFLICT'});expect(await db.afterSaleMaterialVersion.count({where:{afterSaleId:same[0]!.afterSaleId}})).toBe(1);},180000);
it('审核必须领取；拒绝与撤销竞争最多一次，旧权限与他人订单拒绝',async()=>{const f=await paid(),a=await apply(f),b={...await saleBody(a.afterSaleId),decision:'REJECT' as const,publicExplanation:'拒绝原因'};await expect(sales().review(support,a.afterSaleId,b)).rejects.toMatchObject({code:'TASK_NOT_ASSIGNEE'});await saleTask(a.afterSaleId);const calls=await Promise.allSettled([sales().review(support,a.afterSaleId,{...b,...await saleBody(a.afterSaleId)}),sales().withdraw(f.c,a.afterSaleId,await saleBody(a.afterSaleId))]);expect(calls.filter(r=>r.status==='fulfilled')).toHaveLength(1);expect(await db.afterSaleDecision.count({where:{afterSaleId:a.afterSaleId}})).toBe(1);await expect(detail(a.afterSaleId,await customer())).rejects.toMatchObject({code:'AFTER_SALE_NOT_FOUND'});await expect(sales().review(warehouse,a.afterSaleId,b)).rejects.toMatchObject({code:'FORBIDDEN'});});
it('仅退款未交运等待实物；已交运待退款，无退款执行或库存回补',async()=>{const f=await paid(),a=await apply(f);await review(a.afterSaleId,'APPROVE');expect((await detail(a.afterSaleId,f.c)).status).toBe('WAIT_FULFILLMENT_CHECK');expect(await db.taskBusinessSource.count({where:{sourceType:'AFTER_SALE',sourceId:a.afterSaleId,status:'ACTIVE'}})).toBe(1);const g=await shipped(),b=await apply(g);await review(b.afterSaleId,'APPROVE');expect((await detail(b.afterSaleId,g.c)).status).toBe('WAIT_REFUND');expect(await db.task.findFirst({where:{businessId:b.afterSaleId,stage:'REFUND_PROCESS'}})).toMatchObject({status:'OPEN'});await expect(sales().close(support,b.afterSaleId,{...await saleBody(b.afterSaleId,'REFUND_PROCESS'),reason:'不得关闭',publicExplanation:'不得关闭'})).rejects.toMatchObject({code:'AFTER_SALE_CLOSE_FORBIDDEN'});expect(await db.inventoryBalance.findUnique({where:{skuId:g.sku.id}})).toMatchObject({available:8,reserved:0});});
