async function resolveException(id:string,e:string){await claim(id,'SHIPMENT_EXCEPTION_VERIFY');await claim(id,'CUSTOMER_CONTACT',support);const b=async(stage:TaskStage)=>({...await body(id,stage),expectedExceptionVersion:(await db.shipmentException.findUniqueOrThrow({where:{id:e}})).version,currentPhysicalVersion:(await db.order.findUniqueOrThrow({where:{id}})).stockPhysicalVersion,evidenceNote:'已实际核实本异常'});await fulfillment.warehouseReady(warehouse,id,e,{...await b('SHIPMENT_EXCEPTION_VERIFY'),goodsLocation:'异常已核对货架',items:(await packing(id)).items});await fulfillment.customerChoice(support,id,e,{...await b('CUSTOMER_CONTACT'),choice:'CONTINUE'});await fulfillment.resolveException(warehouse,id,e,await b('SHIPMENT_EXCEPTION_VERIFY'));}
