// 审计屏障位于正式事务末尾，确保先取得领域锁的动作提交前，第二动作已经发起。
async function arbitrated<T,U>(matches:(p:AuditPayload)=>boolean,first:()=>Promise<T>,second:()=>Promise<U>){
 let entered!:()=>void,release!:()=>void;
 const reached=new Promise<void>(r=>entered=r),gate=new Promise<void>(r=>release=r);
 audit.barrier={matches,entered,release:gate};
 const a=first();await Promise.race([reached,a.then(()=>{throw new Error('屏障未命中');})]);
 const b=second();release();return Promise.allSettled([a,b]);
}
it.each(['apply-first','start-first'] as const)('售后与开始交运按真实事务屏障仲裁：%s',async order=>{
 const f=await ready(),b=await body(f.id),q=await app.get(FulfillmentQueries).detail(warehouse,f.id);
 const startBody={...b,shipmentId:q.shipment!.id,packingCheckId:q.packingCheck!.id,expectedPhysicalVersion:q.physicalVersion};
 const go=()=>fulfillment.start(warehouse,f.id,startBody);
 const r=order==='apply-first'?await arbitrated(p=>p.action==='after-sale.change',()=>apply(f),go):await arbitrated(p=>p.action==='order.fulfillment'&&p.after?.fulfillmentAction==='START',go,()=>apply(f));
 expect(r[0]!.status).toBe('fulfilled');
 if(order==='apply-first'){expect(r[1]!.status).toBe('rejected');expect(await db.handoverAttempt.count({where:{orderId:f.id}})).toBe(0);}
 else{expect(r[1]!.status).toBe('fulfilled');expect(await db.handoverAttempt.findFirst({where:{orderId:f.id}})).toMatchObject({status:'UNCERTAIN'});}
 expect(await db.orderBlock.count({where:{orderId:f.id,sourceType:'AFTER_SALE',active:true}})).toBe(1);
});
it.each(['apply-first','confirm-first'] as const)('售后与真实交包确认屏障仲裁：%s',async order=>{
 const f=await ready(),a=await start(f.id),b={...await body(f.id),attemptId:a.attemptId!,expectedAttemptVersion:a.attemptVersion!,actualHandoverAt:clock.now().toISOString()},go=()=>fulfillment.confirm(warehouse,f.id,b);
 const r=order==='apply-first'?await arbitrated(p=>p.action==='after-sale.change',()=>apply(f),go):await arbitrated(p=>p.action==='order.fulfillment'&&p.after?.fulfillmentAction==='CONFIRM',go,()=>apply(f));
 expect(r[0]!.status).toBe('fulfilled');if(order==='apply-first')expect(r[1]!.status).toBe('rejected');else{expect(r[1]!.status).toBe('fulfilled');expect(await db.order.findUnique({where:{id:f.id}})).toMatchObject({status:'SHIPPED',autoReceiptDueAt:null});}
 expect(await db.afterSale.count({where:{orderId:f.id}})).toBe(1);
});
it.each(['active','automatic'] as const)('申请与%s收货各先后，完成不降级',async mode=>{
 for(const first of ['apply','receipt']){
  const f=await shipped();if(mode==='automatic')clock.value=(await db.order.findUniqueOrThrow({where:{id:f.id}})).autoReceiptDueAt!;
  const receipt=()=>mode==='active'?fulfillment.confirmReceipt(f.c,f.id):fulfillment.autoReceipt(f.id);
  const r=first==='apply'?await arbitrated(p=>p.action==='after-sale.change',()=>apply(f),receipt):await arbitrated(p=>p.action==='order.receipt',receipt,()=>apply(f));
  expect(r[0]!.status).toBe('fulfilled');
  if(first==='receipt'){expect(r[1]!.status).toBe('fulfilled');expect(await db.order.findUnique({where:{id:f.id}})).toMatchObject({status:'COMPLETED',autoReceiptDueAt:null});}
  else{expect(await db.order.findUnique({where:{id:f.id}})).toMatchObject({status:'SHIPPED',completedAt:null});if(mode==='active')expect(r[1]!.status).toBe('rejected');else expect((r[1] as PromiseFulfilledResult<unknown>).value).toMatchObject({skipped:true});}
  clock.followWallClock();
 }
});
